tool_input.command:
node -e '
function test(locale) {
  try {
    const f = new Intl.DateTimeFormat(locale, {year:"numeric"});
    console.log(JSON.stringify(locale), "-> OK, resolved locale:", f.resolvedOptions().locale);
  } catch (e) {
    console.log(JSON.stringify(locale), "-> THROWS:", e.constructor.name, e.message);
  }
}
test("not-a-locale!!");
test(undefined);
test("xx-YY");
test("en-US");
test("");
test("123");
test("en_US");
test("this is not bcp47 at all with spaces");
'

